INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ORTH_ALEXANDRA_FEODOROVNA_SYNAX','ENT_ORTH_ALEXANDRA_FEODOROVNA','SRC_SYNAXARION','The Synaxarion','The Synaxarion','And on this day also became martyrs Yarewenyos, and many men and women, and Negirus (Longinus) of Rome, Alexandra who visited Arsenius, and ‘Awshia. Glory be to God Who is glorified in His Saints. Amen. TIR 06 (January 14) IN THE NAME OF THE FATHER AND THE SON AND THE HOLY SPIRIT, ONE GOD. AMEN.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_BASIL_SYNAX','ENT_ORTH_BASIL','SRC_SYNAXARION','The Synaxarion','The Synaxarion','This saint was brought up with Basil the Great, and he made him a priest; and he was of goodly appearance, and his face was very pleasing. As a young man his first act was to desire the governor''s wife, for he loved her dearly, and she loved him, and they made a plan together to go to another place where they could fulfill their desires.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_CHRYSOSTOM_SYNAX','ENT_ORTH_CHRYSOSTOM','SRC_SYNAXARION','The Synaxarion','The Synaxarion','17 Translation of the body of St John Chrysostom. Abraham, Harik, Shenuti, Kedus ‘Amlak, Walatta Petros. 18 Atrasis and Yona, Philip the Apostle. Eleutherus and Entia. 19 Consecration of the Church of Sergius and Bacchus. Bartholomew, Theophilus and Patricia and Damalis. 20 Archbishop Anianus. Consecration of the Church of Theodore. 21 Festival of the Virgin Mary. Gregory the Thaumaturge (i.e. the Theologian), Archbishop Cosmas.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_CYRIL_METHODIUS_SYNAX','ENT_ORTH_CYRIL_METHODIUS','SRC_SYNAXARION','The Synaxarion','The Synaxarion','And Abba Cyril, Archbishop of the city of Alexandria, sent forth his testimony concerning the Word, and he said, "The union of the Word of God with the flesh is like the union of the spirit with the body, and like the union of fire with iron.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_GREGORY_THEOLOGIAN_SYNAX','ENT_ORTH_GREGORY_THEOLOGIAN','SRC_SYNAXARION','The Synaxarion','The Synaxarion','And on this day also died Gregory the Theologian. And on this day also died Abba ‘Akresteros (Christopher) the fighter. This saint lived in the desert of the Jordan, and one of the monks bowed before him and entreated him, THE ETHIOPIAN SYNAXARIUM 327 saying, "O my father ‘Akresteros (Christopher), do me an act of grace, and describe to me all thy manner of life and work so that I may profit thereby." And the elder said unto him, "O my son, when I became a','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_IGNATIUS_BRIANCHANINOV_SYNAX','ENT_ORTH_IGNATIUS_BRIANCHANINOV','SRC_SYNAXARION','The Synaxarion','The Synaxarion','THE ETHIOPIAN SYNAXARIUM 234 And on this day also the holy and honorable Ignatius, Archbishop of Antioch, became a martyr. This saint was the disciple of the blessed John the evangelist, and he followed him in preaching, and he went with him to many cities; and after this, John made him Archbishop of Antioch, and he preached the doctrine, which maketh alive therein.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_JUSTIN_POPOVIC_SYNAX','ENT_ORTH_JUSTIN_POPOVIC','SRC_SYNAXARION','The Synaxarion','The Synaxarion','And on this day also are commemorated Labiba (Liba), and ‘Akiryanos (Cirianus), and Justin, and Tekaseltes (Tekaleltes). Glory be to God Who is glorified in His Saints. Amen. Meskerem 18 (September 28) IN THE NAME OF THE FATHER AND THE SON AND THE HOLY SPIRIT, ONE GOD. AMEN. On this day died Eustathius, a teacher of the faith and a preacher of the Gospel.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_MARIA_SKOBTSOVA_SYNAX','ENT_ORTH_MARIA_SKOBTSOVA','SRC_SYNAXARION','The Synaxarion','The Synaxarion','And on this day also are commemorated Lestelia, and Mekrona, and Mariana, and Philopator, and ‘Abrani, and the Emperor Honorius. Glory be to God Who is glorified in His Saints. Amen. HEDAR 14 (November 23) IN THE NAME OF THE FATHER AND THE SON AND THE HOLY SPIRIT, ONE GOD. AMEN. On this day died the holy father Canitus, that is to say Marcius (Martianus), Bishop of the country of Thrace.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_MARY_EGYPT_SYNAX','ENT_ORTH_MARY_EGYPT','SRC_SYNAXARION','The Synaxarion','The Synaxarion','St Mary of Egypt). The appearance of our Lord to Thomas. The deaths of Adam and Eve. Births of Noah and David, King of Israel. 7 Joachim, father of the Virgin Mary. ‘Agabos and Theodora. Metruf, son of Abba Muse. 8 ‘Agali, ‘Erani and Susnonya. One hundred and fifty martyrs in Persia. Timothy the archbishop. 9 Zozimas. Isidore and his fellow martyrs. Shenuti, Archbishop of Alexandria. 10 Isaac, disciple of Apollo. Gabriel, Archbishop of Alexandria.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_MATRONA_MOSCOW_SYNAX','ENT_ORTH_MATRONA_MOSCOW','SRC_SYNAXARION','The Synaxarion','The Synaxarion','And on this day also died Saint Matrona, and Saint Justus, and his wife, who became martyrs. [Omitted in the Bodleian MS.] Glory be to God Who is glorified in His Saints. Amen. Miyazia 02 (April 10) IN THE NAME OF THE FATHER AND THE SON AND THE HOLY SPIRIT, ONE GOD. AMEN. And on this day died Saint Christopher, the martyr, whose face was like the face of a dog. This holy man came from the country, the people whereof used to eat men and dogs.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_MENAS_SYNAX','ENT_ORTH_MENAS','SRC_SYNAXARION','The Synaxarion','The Synaxarion','This just man Gideon was of the tribe of Menasseh and his father''s name was Joas; and the angel of the Lord appeared and helped him, and strengthened him, and made him judge over the children of Israel. And he commanded him to destroy the altar of idols, and to build an altar to God, and to offer up burnt offerings upon it; and Gideon burnt with fire the wooden idols, which were broken in pieces, and he did as the Lord commanded.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_ROYAL_MARTYRS_SYNAX','ENT_ORTH_ROYAL_MARTYRS','SRC_SYNAXARION','The Synaxarion','The Synaxarion','This happened in the ninth year of Archbishop Abba Macarius, in the eight hundred and twenty- eighth year of the Holy Martyrs [A.D. 1112]. May their prayers and blessing be with us. Amen. And on this day are commemorated Dioscoros the martyr, and Archbishop Dionysius, and the martyrs who were in Tensel Yakoton, and many martyrs in Persia. May their prayer and blessing, etc. And on this day died Abba ‘Anbes (Father Lion) of the country of Ethiopia.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_SERAPHIM_SYNAX','ENT_ORTH_SERAPHIM','SRC_SYNAXARION','The Synaxarion','The Synaxarion','Seraphim and Cherubim surrounded Him, and His awe and majesty were exceedingly great. Each of these had six wings; with two of their wings they covered their faces, with two of their wings they covered their feet, and with two of their wings they did fly in the greatest glory by day and by night, saying, Holy, Holy, Holy, Lord God of Hosts. All the heavens and the earth are filled with the holiness of Thy glory" (Isaiah vi, 2).','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_SERGIUS_SYNAX','ENT_ORTH_SERGIUS','SRC_SYNAXARION','The Synaxarion','The Synaxarion','On this day Saint Bacchus and his companion Saint Sergius became martyrs by the hands of the wicked Antiochus, governor of Syria. Now this took place when the Emperor Maximianus seized these saints, and tortured them with sever tortures after he had cast off their belts, for they were soldiers. After this he sent them to the country of Syria, to Antiochus the governor, who shut Saint Bacchus and Saint Sergius up in prison.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_SIMEON_STYLITES_SYNAX','ENT_ORTH_SIMEON_STYLITES','SRC_SYNAXARION','The Synaxarion','The Synaxarion','And he read continually the history of the striving of Abba Simon of the pillar (Simon Stylites), and he was always envious of his striving. And he meditated in his heart, shutting himself up, and he took counsel with the holy fathers concerning it, and they said this counsel is good; and he was blessed by them and they prayed over him. And he went out of the desert, and came nigh unto the world, to the city of Saka (i.e.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_THEODORE_SYNAX','ENT_ORTH_THEODORE','SRC_SYNAXARION','The Synaxarion','The Synaxarion','s who suffered in Antioch, and ‘Enteya, one of the Seventy, of the people of ‘Ensena, and Theodore the bishop, from Debra ‘Eldanu, and theologian. Glory be to God Who is glorified in His Saints. Amen. Meskerem 05 (September 15) IN THE NAME OF THE FATHER AND THE SON AND THE HOLY SPIRIT, ONE GOD. AMEN.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_THREE_HIERARCHS_SYNAX','ENT_ORTH_THREE_HIERARCHS','SRC_SYNAXARION','The Synaxarion','The Synaxarion','And he also excommunicated THE ETHIOPIAN SYNAXARIUM 13 every one who departed from the Orthodox Faith, which our fathers the Apostles, and our holy fathers the Three Hundred and Eighteen Orthodox bishops who assembled in Nicea laid down. And the emperor was wroth, and he commanded that Dioscoros should be banished to the island of Gagra. And they took him there, and with him was Abba Macarius, bishop of the city of Kaw, and four others fled.','trans.',1900,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify the commemoration date.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
